// Imports — the tools and DSP definitions used by this instrument.
import { createGraphWorkspace, parameterValue } from '@manifold/author';
import { oscillator, lfo, modulatedGain, gain } from '@manifold/author/primitives';
import { defineNetwork } from '@manifold/author/host-services';

export default function createProject() {
  // Interface — four controls shared by the graph, UI and external messages.
  const controls = {
    pitch: {
      id: 'tone', path: '/network/tone', label: 'Tone', unit: 'Hz',
      min: 40, max: 2000, default: 220,
    },
    pulseRate: {
      id: 'pulse', path: '/network/pulse', label: 'Pulse rate', unit: 'Hz',
      min: 0.1, max: 20, default: 2,
    },
    volume: {
      id: 'volume', path: '/network/volume', label: 'Volume',
      min: 0, max: 1, default: 0.7,
    },
    playback: {
      id: 'play', path: '/network/play', label: 'Playback gate',
      min: 0, max: 1, default: 1,
    },
  };

  // Graph definition — this instrument generates sound; it needs no audio input.
  const graph = createGraphWorkspace().setInputSource('none');
  const output = graph.output.input('in');

  // These stable instance IDs keep existing saved projects and automation valid.
  const tone = graph.add(oscillator.type, { id: 4 });
  const pulse = graph.add(lfo.type, { id: 5 });
  const movement = graph.add(modulatedGain.type, { id: 6 });
  const volume = graph.add(gain.type, { id: 7 });
  const playback = graph.add(gain.type, { id: 8 });

  tone.parameter('frequency').expose(controls.pitch);
  pulse.parameter('rate').expose(controls.pulseRate);
  volume.parameter('level').expose(controls.volume);
  playback.parameter('level').expose(controls.playback);

  // Keep the voice quiet. The unipolar LFO moves its gain from half to full level.
  tone.parameter('level').set(0.16);
  movement.parameter('base').set(0.5);
  movement.parameter('depth').set(0.5);

  graph.connect(tone.output('out'), movement.input('audio'));
  graph.connect(pulse.output('uni'), movement.input('cv'));
  graph.connect(movement.output('out'), volume.input('audio'));
  graph.connect(volume.output('out'), playback.input('audio'));
  graph.connect(playback.output('out'), output);

  // External inputs — port zero asks the host to choose an available port.
  // TCP: one JSON object per line. UDP: one JSON object per packet.
  // Both accept { "path": "/network/tone", "value": 440 }.
  // OSC uses the same control path and one numeric argument.
  const network = defineNetwork({
    tcp: '127.0.0.1:0',
    udp: '127.0.0.1:0',
    osc: '127.0.0.1:0',
    oscQuery: '127.0.0.1:0',
    link: { enabled: false, tempo: 120, quantum: 4, startStopSync: false },
  });

  // The host opens these services when networking is connected. It decodes
  // incoming TCP/UDP/OSC/Link events and delivers them to this handler.
  // Declaring a network here does not open sockets during graph compilation.
  network.onEvent(onNetwork);

  // Live behavior — messages become ordinary acknowledged control edits.
  function onNetwork(event, accepted) {
    if (event.type === 'link') {
      return followLink(event.state, accepted.graph);
    }

    const message = event.type === 'osc'
      ? { path: event.path, value: event.args[0] }
      : event.message;

    if (!message || typeof message.path !== 'string' || !Number.isFinite(message.value)) {
      throw new Error('Expected a parameter path and a finite numeric value');
    }

    // Try changing message.value to message.value / 2, then Apply while playing.
    // The runtime validates the path/range and accepts the audio edit before replying.
    return {
      command: { operation: 'parameter.set', path: message.path, value: message.value },
      reply: { accepted: true, path: message.path },
    };
  }

  function followLink(transport, acceptedGraph) {
    const edits = [];

    if (transport.tempoSync) {
      // One pulse per beat: beats per minute / 60 = pulses per second (Hz).
      // This follows tempo; the LFO's phase is independent of Link's beat clock.
      const rate = transport.tempo / 60;
      const currentRate = parameterValue(acceptedGraph, controls.pulseRate.path);
      if (Math.abs(currentRate - rate) > 0.0001) {
        edits.push({ path: controls.pulseRate.path, value: rate });
      }
    }

    // A separate gate lets transport stop sound without changing the volume knob.
    const playing = transport.startStopSync ? Number(transport.playing) : 1;
    if (parameterValue(acceptedGraph, controls.playback.path) !== playing) {
      edits.push({ path: controls.playback.path, value: playing });
    }

    if (edits.length === 0) return null;
    return { command: { operation: 'parameter.batch', edits } };
  }

  // Presentation — retained and egui views bind to the same declared controls.
  const view = [
    slider(controls.pitch),
    slider(controls.pulseRate),
    slider(controls.volume),
    slider(controls.playback),
  ];

  function slider(control) {
    return {
      id: control.id, type: 'parameter', path: control.path,
      label: control.label, ...(control.unit ? { unit: control.unit } : {}),
    };
  }

  return { graph, view, network };
}

const {createGraphWorkspace}=manifold;
const parameters={
  "/dsp/live/input_gain": {
    "nodeId": 4,
    "id": 0,
    "min": 0,
    "max": 2,
    "default": 1
  },
  "/dsp/live/width": {
    "nodeId": 5,
    "id": 0,
    "min": 0,
    "max": 1,
    "default": 0.25
  }
};
function buildGraph() {
  const graph = createGraphWorkspace().setInputSource('external');
  const gain = graph.add('gain', { id: 4 });
  const width = graph.add('stereo-widener', { id: 5 });
  graph.registerInstance('/dsp/live/nodes/input_trim', gain);
  graph.registerInstance('/dsp/live/nodes/width', width);
  graph.setParameter(gain, 0, parameters['/dsp/live/input_gain'].default);
  graph.setParameter(width, 0, parameters['/dsp/live/width'].default);
  graph.registerParameter('/dsp/live/input_gain', gain, 0, parameters['/dsp/live/input_gain']);
  graph.registerParameter('/dsp/live/width', width, 0, parameters['/dsp/live/width']);
  graph.bindHostSlot(0, gain, 0);
  graph.bindHostSlot(1, width, 0);
  graph.connect(graph.input.output('out'), gain.input('audio'));
  graph.connect(gain.output('out'), width.input('audio'));
  graph.connect(width.output('out'), graph.output.input('in'));
  return graph;
}
const graph=buildGraph();
const enablePath='/dsp/live/distortion_enabled';
graph.registerControl(enablePath,{min:0,max:1,default:0,discrete:true});
function reconcile(graph){
  const enabled=graph.findControl(enablePath).value===1;
  const gain=graph.findInstance('/dsp/live/nodes/input_trim');
  const width=graph.findInstance('/dsp/live/nodes/width');
  const existing=graph.findInstance('/dsp/live/nodes/distortion');
  if(enabled && !existing){
    const distortion=graph.add('distortion',{id:6});
    graph.registerInstance('/dsp/live/nodes/distortion',distortion);
    graph.setParameter(distortion,0,4);graph.setParameter(distortion,1,1);graph.setParameter(distortion,2,1);
    graph.disconnect(width.input('audio'));
    graph.connect(gain.output('out'),distortion.input('audio'));
    graph.connect(distortion.output('out'),width.input('audio'));
  }else if(!enabled && existing){
    graph.remove(existing);graph.connect(gain.output('out'),width.input('audio'));
  }
}
function onControl(session){session.transaction(reconcile);}
const view=[
  {id:'gain',type:'parameter',path:'/dsp/live/input_gain',label:'Input gain'},
  {id:'width',type:'parameter',path:'/dsp/live/width',label:'Width'},
  {id:'insert',type:'control',path:enablePath,label:'Distortion insert',choices:['Off','On']},
];
function paint(ui){for(const component of view)ui[component.type](component.path,component);}
return {graph,view,paint,onControl,reconcile};

const {createGraphWorkspace,GraphContractError}=manifold;
const SLOT={
  "slotA": {
    "source": 4,
    "gain": 6,
    "gate": 7,
    "mix": 8,
    "width": 14,
    "widthGate": 15
  },
  "slotB": {
    "source": 8,
    "gain": 10,
    "gate": 11,
    "mix": 12,
    "width": 16,
    "widthGate": 17
  }
};
const selectPath=(name => `/test/fxslot/${name}/select`);
const amountPath=((name, effect) => `/test/fxslot/${name}/${effect}/amount`);
const nodePath=((name, role) => `/test/fxslot/${name}/nodes/${role}`);
const required=((graph, path) => {
  const node = graph.findInstance(path);
  if (!node) throw new GraphContractError('missing-instance', `Missing graph instance: ${path}`);
  return node;
});
const nextId=((graph, preferred) => {
  if (!graph.find(preferred)) return preferred;
  for (let id = 2; id <= 65535; id++) if (!graph.find(id)) return id;
  throw new GraphContractError('project-size', 'No free graph node IDs');
});
const inputPath="/test/fxslot/nodes/input_trim", masterPath="/test/fxslot/nodes/master";
function buildGraph() {
  const graph = createGraphWorkspace().setInputSource('external');
  const inputTrim = graph.add('gain', { id: 4 });
  graph.registerInstance(inputPath, inputTrim);
  graph.setParameter(inputTrim, 0, 1);
  graph.registerParameter('/test/fxslot/input_gain', inputTrim, 0,
    { min: 0, max: 2, default: 1 });
  graph.bindHostSlot(0, inputTrim, 0);
  graph.connect(graph.input.output('out'), inputTrim.input('audio'));
  for (const [name, ids] of Object.entries(SLOT)) {
    const source = graph.find(ids.source);
    const gain = graph.add('gain', { id: ids.gain });
    const gate = graph.add('gain', { id: ids.gate });
    const mix = graph.add('sum2', { id: ids.mix });
    graph.registerInstance(nodePath(name, 'gain'), gain);
    graph.registerInstance(nodePath(name, 'gain_gate'), gate);
    graph.registerInstance(nodePath(name, 'mix'), mix);
    graph.setParameter(gain, 0, 0.8);
    graph.setParameter(gate, 0, 1);
    graph.connect(source.output('out'), gain.input('audio'));
    graph.connect(gain.output('out'), gate.input('audio'));
    graph.connect(gate.output('out'), mix.input('a'));
    graph.registerControl(selectPath(name), { min: 0, max: 1, default: 0, discrete: true });
    graph.registerControl(amountPath(name, 'gain'), { min: 0, max: 2, default: 0.8 });
    graph.registerControl(amountPath(name, 'width'), { min: 0, max: 2, default: 1.6 });
  }
  const master = graph.add('gain', { id: 13 });
  graph.registerInstance(masterPath, master);
  graph.setParameter(master, 0, 1);
  graph.connect(graph.find(12).output('out'), master.input('audio'));
  graph.connect(master.output('out'), graph.output.input('in'));
  return graph;
}
function slotName(path) {
  return Object.keys(SLOT).find(name => path.startsWith(`/test/fxslot/${name}/`));
}
function applySlot(graph, path, value) {
  const name = slotName(path);
  if (!name || !Number.isFinite(value)) {
    throw new GraphContractError('unknown-control', `Unknown FX slot control: ${path}`);
  }
  const ids = SLOT[name];
  if (path === selectPath(name)) {
    const selected = Math.max(0, Math.min(1, Math.floor(value + 0.5)));
    graph.setControl(path, selected);
    const widthPath = nodePath(name, 'width');
    const gatePath = nodePath(name, 'width_gate');
    if (selected === 1 && !graph.findInstance(widthPath)) {
      const width = graph.add('stereo-widener', { id: nextId(graph, ids.width) });
      const gate = graph.add('gain', { id: nextId(graph, ids.widthGate) });
      graph.registerInstance(widthPath, width);
      graph.registerInstance(gatePath, gate);
      graph.setParameter(width, 0, graph.findControl(amountPath(name, 'width')).value);
      graph.setParameter(width, 1, 160);
      graph.setParameter(width, 2, 1);
      graph.setParameter(gate, 0, 0);
      const source = name === 'slotA' ? inputPath : nodePath('slotA', 'mix');
      graph.connect(required(graph, source).output('out'), width.input('audio'));
      graph.connect(width.output('out'), gate.input('audio'));
      graph.connect(gate.output('out'), required(graph, nodePath(name, 'mix')).input('b'));
    }
    graph.setParameter(required(graph, nodePath(name, 'gain_gate')), 0, selected === 0 ? 1 : 0);
    if (graph.findInstance(gatePath)) {
      graph.setParameter(required(graph, gatePath), 0, selected === 1 ? 1 : 0);
    }
    return;
  }
  for (const effect of ['gain', 'width']) {
    if (path !== amountPath(name, effect)) continue;
    graph.setControl(path, value);
    const node = graph.findInstance(nodePath(name, effect));
    if (node) graph.setParameter(node, 0, value);
    return;
  }
  throw new GraphContractError('unknown-control', `Unknown FX slot control: ${path}`);
}
function reconcileSlots(graph, previous) {
  for(const name of Object.keys(SLOT)) {
    const visited=previous.instances?.some(entry=>entry.path===nodePath(name,'width'));
    const selection=graph.findControl(selectPath(name)).value;
    if(visited && !graph.findInstance(nodePath(name,'width')))applySlot(graph,selectPath(name),1);
    // Stored amounts are the canonical per-effect memory, including inactive effects.
    for(const effect of ['gain','width'])applySlot(graph,amountPath(name,effect),graph.findControl(amountPath(name,effect)).value);
    applySlot(graph,selectPath(name),selection);
  }
}
const graph=buildGraph();
const view=[{id:'input',type:'parameter',path:'/test/fxslot/input_gain',label:'Input gain',group:'Routing'}];
for(const name of Object.keys(SLOT)){
  const group=name==='slotA'?'Slot A':'Slot B';
  view.push({id:name+'-select',type:'control',path:selectPath(name),label:'Effect',choices:['Gain','Width'],group});
  for(const effect of ['gain','width'])view.push({id:name+'-'+effect,type:'control',path:amountPath(name,effect),label:effect==='gain'?'Gain amount':'Width amount',group});
}
function onControl(session,path,value){session.transaction(graph=>applySlot(graph,path,value));}
function paint(ui){for(const component of view)ui[component.type](component.path,component);}
return {graph,view,paint,onControl,reconcile:reconcileSlots};

// Gain: Scale the incoming audio.
// Audition composition of public Rust primitives; not an instrument parity claim.
const {createGraphWorkspace}=manifold;
const graph=createGraphWorkspace().setInputSource("external");
const nodes=[
  {
    "id": 4,
    "type": "gain",
    "name": "node",
    "values": {
      "0": 1
    }
  }
];
for(const spec of nodes){
  const node=graph.add(spec.type,{id:spec.id,...(spec.args ?? {})});
  graph.registerInstance('/primitives/gain/'+spec.name,node);
  for(const [parameter,value]of Object.entries(spec.values ?? {}))graph.setParameter(node,Number(parameter),value);
}
const parameters=[
  {
    "nodeId": 4,
    "id": 0,
    "path": "/primitives/gain/node/0",
    "min": 0,
    "max": 2,
    "default": 1
  }
];
for(const parameter of parameters){
  const node=graph.find(parameter.nodeId);
  graph.setParameter(node,parameter.id,parameter.default);
  graph.registerParameter(parameter.path,node,parameter.id,parameter);
}
const connections=[[1,"out",4,"audio"],[4,"out",3,"in"]];
for(const [from,output,to,input]of connections)graph.connect(graph.find(from).output(output),graph.find(to).input(input));
const view=[
  {
    "id": "/primitives/gain/node/0",
    "type": "parameter",
    "path": "/primitives/gain/node/0",
    "label": "Level",
    "group": "Gain"
  }
];
function paint(ui){for(const component of view){if(component.type==='label')ui.label(component.label,component.id);else ui.parameter(component.path,component);}}
return {graph,view,paint};

