const { createGraphWorkspace, GraphContractError } = manifold;
const OSC_BASE = '/midi/synth/rack/osc/1';
const hz = note => 440 * 2 ** ((note - 69) / 12);
const voicePath = index => `${OSC_BASE}/voice/${index}`;
const oscillatorPath = index => `${OSC_BASE}/nodes/${index === 9 ? 'manual' : `voice_${index}`}`;

/** Add the original eight voices, manual voice, nine-input mixer, and output gain. */
function addRackOscillatorModule(graph, { firstVoiceId = 4, mixerId = 13,
  outputId = 21, connectOutput = false } = {}) {
  const oscillators = [];
  for (let index = 1; index <= 9; index++) {
    const oscillator = graph.add('extended-oscillator', { id: firstVoiceId + index - 1 });
    graph.registerInstance(oscillatorPath(index), oscillator);
    graph.setParameter(oscillator, 0, 1);
    graph.setParameter(oscillator, 1, index === 9 ? hz(60) : 220);
    graph.setParameter(oscillator, 2, 0);
    if (index <= 8) graph.setParameter(oscillator, 9, 1);
    oscillators.push(oscillator);
  }
  const mixer = graph.add('mixer9', { id: mixerId });
  graph.registerInstance(`${OSC_BASE}/nodes/mixer`, mixer);
  for (let index = 0; index < oscillators.length; index++) {
    graph.connect(oscillators[index].output('out'), mixer.input(`in-${index + 1}`));
  }
  const output = graph.add('gain', { id: outputId });
  graph.registerInstance(`${OSC_BASE}/nodes/output`, output);
  graph.setParameter(output, 0, 0.2);
  graph.connect(mixer.output('out'), output.input('audio'));
  if (connectOutput) graph.connect(output.output('out'), graph.output.input('in'));

  for (const [suffix, range] of Object.entries({
    waveform: { min: 0, max: 7, default: 1, discrete: true },
    drive: { min: 0, max: 20, default: 0 },
    driveShape: { min: 0, max: 3, default: 0, discrete: true },
    driveBias: { min: -1, max: 1, default: 0 },
    pulseWidth: { min: 0.01, max: 0.99, default: 0.5 },
    unison: { min: 1, max: 8, default: 1, discrete: true },
    detune: { min: 0, max: 100, default: 0 },
    spread: { min: 0, max: 1, default: 0 },
    renderMode: { min: 0, max: 1, default: 0, discrete: true },
    additivePartials: { min: 1, max: 32, default: 8, discrete: true },
    additiveTilt: { min: -1, max: 1, default: 0 },
    additiveDrift: { min: 0, max: 1, default: 0 },
    manualPitch: { min: 0, max: 127, default: 60 },
    manualLevel: { min: 0, max: 1, default: 0 },
    output: { min: 0, max: 2, default: 0.8 },
  })) graph.registerControl(`${OSC_BASE}/${suffix}`, range);
  for (let index = 1; index <= 8; index++) {
    for (const [suffix, range] of Object.entries({
      gate: { min: 0, max: 1, default: 0 },
      vOct: { min: 0, max: 127, default: 60 },
      fm: { min: -1, max: 1, default: 0 },
      pwCv: { min: 0, max: 1, default: 0.5 },
    })) graph.registerControl(`${voicePath(index)}/${suffix}`, range);
  }
  return output;
}

function buildGraph() {
  const graph = createGraphWorkspace();
  addRackOscillatorModule(graph, { connectOutput: true });
  return graph;
}

/** Interpret old path controls against any prepared graph containing this module. */
function setRackOscillatorControl(session, path, value) {
  const project = session.toProject();
  const values = new Map(project.controls.map(entry => [entry.path, entry.value]));
  if (!values.has(path)) throw new GraphContractError('unknown-control', `Unknown oscillator control: ${path}`);
  const instances = new Map(project.instances.map(entry => [entry.path, entry.nodeId]));
  const node = index => instances.get(oscillatorPath(index));
  const output = instances.get(`${OSC_BASE}/nodes/output`);
  if (!output || Array.from({ length: 9 }, (_, index) => node(index + 1)).some(id => !id)) {
    throw new GraphContractError('unsupported-project', 'Rack oscillator nodes are missing');
  }
  const suffix = path.slice(path.lastIndexOf('/') + 1);
  const control = { path, value };
  if (suffix === 'output') return session.parameterWithControl(
    { nodeId: output, id: 0, value: value * 0.25 }, control);
  if (suffix === 'manualPitch') return session.parameterWithControl(
    { nodeId: node(9), id: 1, value: Math.max(20, Math.min(8000, hz(value))) }, control);
  if (suffix === 'manualLevel') return session.parameterWithControl(
    { nodeId: node(9), id: 2, value: value * 0.4 }, control);
  const match = path.match(/\/voice\/(\d+)\/(gate|vOct|fm|pwCv)$/);
  if (match) {
    const index = Number(match[1]);
    const base = voicePath(index);
    const get = key => key === suffix ? value : values.get(`${base}/${key}`);
    const edit = suffix === 'gate'
      ? { nodeId: node(index), id: 2, value: Math.min(0.4, Math.max(0, value)) }
      : suffix === 'pwCv'
        ? { nodeId: node(index), id: 4, value: Math.max(0.01, Math.min(0.99,
          values.get(`${OSC_BASE}/pulseWidth`) + value - 0.5)) }
        : { nodeId: node(index), id: 1, value: Math.max(20, Math.min(8000,
          hz(get('vOct') + get('fm') * 12))) };
    return session.parameterWithControl(edit, control);
  }
  const ids = { waveform: 0, drive: 5, driveShape: 6, driveBias: 7, pulseWidth: 4,
    unison: 10, detune: 11, spread: 12, renderMode: 13,
    additivePartials: 14, additiveTilt: 15, additiveDrift: 16 };
  if (Object.hasOwn(ids, suffix)) {
    const edits = Array.from({ length: 9 }, (_, index) => ({ nodeId: node(index + 1),
      id: ids[suffix], value: suffix === 'pulseWidth' && index < 8
        ? Math.max(0.01, Math.min(0.99, value + values.get(`${voicePath(index + 1)}/pwCv`) - 0.5))
        : value }));
    return session.parametersWithControl(edits, control);
  }
  throw new GraphContractError('unknown-control', `Unsupported oscillator control: ${path}`);
}


function chooseMainVoice(voices) {
  const idle = voices.findIndex(v => !v.active || v.envelopeStage === 'idle');
  if (idle >= 0) return idle;
  let release = -1;
  for (let index = 0; index < voices.length; index++) {
    if (voices[index].envelopeStage === 'release' &&
      (release < 0 || voices[index].envelopeLevel < voices[release].envelopeLevel)) release = index;
  }
  if (release >= 0) return release;
  return voices.reduce((oldest, v, index) => v.stamp < voices[oldest].stamp ? index : oldest, 0);
}

// Visual sampling port of Main/lib/ui/oscillator_preview.lua. This produces
// drawing points only. The authored Rust oscillator remains the audio processor.
const previewClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const previewFract=v=>v-Math.floor(v);
function oscillatorPreviewWave(type,p,width){
  p=previewFract(p);
  switch(type){
    case 0:return Math.sin(p*2*Math.PI);
    case 1:return 2*p-1;
    case 2:return p<.5?1:-1;
    case 3:return p<.5?4*p-1:3-4*p;
    case 4:return ((2*p-1)+Math.sin(p*2*Math.PI))*.5;
    case 5:return (previewFract(Math.sin(p*43758.5453))*2-1)*.5;
    case 6:return p<width?1:-1;
    case 7:return ((2*p-1)+(2*previewFract(p*1.01)-1)*.5+(2*previewFract(p*.99)-1)*.5)*.5;
  }
  return 0;
}
function oscillatorPreviewRecipe(type,width){
  const out=[],add=(ratio,amplitude,phase=0)=>{if(amplitude>1e-6&&out.length<12)out.push({ratio,amplitude,phase});};
  if(type===0)add(1,1);
  else if(type===1||type===4)for(let h=1;h<=12;h++)add(h,type===1?1/h:(h===1?.45:0)+.55/h);
  else if(type===2||type===3)for(let i=0;i<12;i++){const h=2*i+1;add(h,type===2?1/h:1/(h*h),type===2?0:(i%2?1:-1)*Math.PI*.5);}
  else if(type===5){const r=[1,1.37,1.93,2.58,3.11,3.93,5.17,6.44,8.13,10.37,13.11,16.51],a=[1,.91,.82,.74,.67,.60,.52,.45,.38,.31,.25,.2],p=[0,.63,1.42,2.17,.88,2.74,1.11,2.49,.37,1.96,2.81,.94];r.forEach((v,i)=>add(v,a[i],p[i]));}
  else if(type===6)for(let h=1;h<=12;h++){const c=Math.sin(Math.PI*h*width);add(h,Math.abs(c)/h,c<0?Math.PI:0);}
  else if(type===7){const d=[-18,-7,0,8,19],g=[.55,.82,1,.79,.5],p=[.17,.51,0,.33,.74];d.forEach((v,i)=>add(2**(v/1200),g[i],p[i]));}
  return out;
}
function oscillatorPreviewDrive(x,drive,shape,bias){
  const clip=v=>previewClamp(v,-1,1);
  if(drive<=.0001)return clip(x);
  const transfer=value=>{
    if(shape===1){const g=1+drive*1.35;return Math.atan(value*g)/Math.atan(g);}
    if(shape===2)return clip(value*(1+drive*1.2));
    if(shape===3){let v=previewClamp(value*(1+drive*1.1),-32,32);while(v>1||v< -1)v=v>1?2-v:-2-v;return v;}
    const g=1+drive*.85;return Math.tanh(value*g)/Math.tanh(g);
  };
  const offset=bias*.75,center=transfer(offset),normal=Math.max(1e-6,Math.abs(transfer(1+offset)-center),Math.abs(transfer(-1+offset)-center));
  return clip((transfer(x+offset)-center)/normal);
}
function oscillatorPreviewCurves(controls){
  const type=controls.waveform??1,width=controls.pulseWidth??.5,add=controls.renderMode===1;
  const recipe=oscillatorPreviewRecipe(type,width).slice(0,Math.max(1,Math.round(controls.additivePartials??8)));
  const tilt=controls.additiveTilt??0,drift=controls.additiveDrift??0;
  const partials=recipe.map(p=>({ratio:Math.max(.1,p.ratio*(1+Math.sin(p.ratio*2.173+type*.53)*drift*.035*(1+p.ratio*.05))),phase:p.phase+Math.sin(p.ratio*1.618+type*.37)*drift*.85,amp:p.amplitude*Math.max(.12,p.ratio**(tilt*.85))}));
  const sum=partials.reduce((s,p)=>s+p.amp,0),trim=[1,.96,.98,1.06,.94,.78,1,.84][type];
  const shape=x=>oscillatorPreviewDrive(x,controls.drive??0,controls.driveShape??0,controls.driveBias??0);
  const count=add?96:200,wave=Array.from({length:count+1},(_,i)=>{const x=i/count;const sample=add?(sum>1e-6?partials.reduce((s,p)=>s+Math.sin(2*Math.PI*x*p.ratio+p.phase)*p.amp,0)/sum*trim:0):oscillatorPreviewWave(type,x,width);return [x,.5-shape(sample)*.425];});
  const drive=Array.from({length:129},(_,i)=>[i/128,.5-shape(i/64-1)*.5]);
  return {wave,drive,color:['#7dd3fc','#38bdf8','#22d3ee','#2dd4bf','#a78bfa','#94a3b8','#f472b6','#fbbf24'][type],label:['SINE','SAW','SQUARE','TRIANGLE','BLEND','NOISE','PULSE','SUPERSAW'][type]+(add?' ADD':'')+' MODE'};
}

