  {id:'keyboard',type:'keyboard',firstNote:48,noteCount:25,group:'Play'},
];
let previewKey='',previewModel;
function paint(ui,snapshot) {
  const controls=Object.fromEntries(snapshot.graph.controls.filter(c=>c.path.startsWith(OSC_BASE+'/')).map(c=>[c.path.slice(OSC_BASE.length+1),c.value]));
  const key=JSON.stringify(['waveform','pulseWidth','renderMode','additivePartials','additiveTilt','additiveDrift','drive','driveShape','driveBias'].map(k=>controls[k]));
  if(key!==previewKey){previewKey=key;previewModel=oscillatorPreviewCurves(controls);}
  const preview=previewModel;
  for (const {path,type,...options} of view) {
    if(type==='curve')ui.curve({...options,points:options.id==='drive-preview'?preview.drive:preview.wave,color:options.id==='drive-preview'?'#f97316':preview.color,label:options.id==='drive-preview'?'DRIVE':preview.label});
    else if(type==='keyboard')ui.keyboard({...options,activeNotes:(snapshot.eventState?.voices ?? []).filter(v=>v.gate).map(v=>v.note)});
    else ui.control(path,options);
  }
}
function onControl(session,path,value) {
  if(path.startsWith(ADSR_BASE+'/')) {
    const id=['attack','decay','sustain','release'].indexOf(path.split('/').at(-1));
    return session.parametersWithControl(Array.from({length:8},(_,i)=>({nodeId:31+i,id,value})),{path,value});
  }
  return setRackOscillatorControl(session,path,value);
}
const eventStateSchema='manifold.rack-oscillator.keyboard.v1';
const envelopeId=index=>31+index;
const startVoice=(session,index,note,amplitude)=>{
  setRackOscillatorControl(session,voicePath(index+1)+'/vOct',note);
  setRackOscillatorControl(session,voicePath(index+1)+'/gate',amplitude);
};
const releaseVoice=(session,index)=>session.parameters([{nodeId:envelopeId(index),id:4,value:0}]);
const silenceVoice=(session,index)=>setRackOscillatorControl(session,voicePath(index+1)+'/gate',0);

// Allocation is project orchestration; envelopes and oscillator samples run in Rust.
const emptyVoice=()=>({active:false,note:null,gate:0,stamp:0,owner:'',channel:0,
  startedAt:0,releasedAt:0,releaseLevel:0,velocity:0,keyDown:0,envelopeStage:'idle',envelopeLevel:0});
const eventState={stamp:0,sustain:{},voices:Array.from({length:8},emptyVoice)};
function onEvent(session,event,state) {
  const project=session.toProject(),controls=new Map(project.controls.map(c=>[c.path,c.value]));
  const get=name=>controls.get(ADSR_BASE+'/'+name);
  const owner=String(event.owner ?? 'user'),channel=event.channel ?? 0;
  if(!Number.isInteger(channel)||channel<0||channel>15)throw new GraphContractError('invalid-event','Invalid MIDI channel');
  const next=structuredClone(state);
  for(const voice of next.voices) {
    const age=Math.max(0,event.at-voice.startedAt);
    if(voice.gate) {
      voice.envelopeLevel=age<get('attack')?age/get('attack'):
        age<get('attack')+get('decay')?1-(1-get('sustain'))*(age-get('attack'))/get('decay'):get('sustain');
      voice.envelopeStage='sustain';
    } else if(voice.active) {
      voice.envelopeLevel=voice.releaseLevel*Math.max(0,1-(event.at-voice.releasedAt)/get('release'));
      voice.envelopeStage=voice.envelopeLevel>0?'release':'idle';
      if(voice.envelopeStage==='idle')voice.active=false;
    }
  }
  if(event.type==='panic') {
    for(const [index,voice] of next.voices.entries()) {
      if((event.owner==null||voice.owner===owner)&&(event.channel==null||voice.channel===channel)) {
        silenceVoice(session,index);
        session.parameters([{nodeId:envelopeId(index),id:4,value:0}]);
        next.voices[index]=emptyVoice();
      }
    }
    for(const key of Object.keys(next.sustain)) {
      const separator=key.lastIndexOf(':');
      if((event.owner==null||key.slice(0,separator)===owner)&&(event.channel==null||Number(key.slice(separator+1))===channel))delete next.sustain[key];
    }
    return next;
  }
  if(event.type==='all-notes-off') {
    for(const [index,voice] of next.voices.entries()) {
      if(voice.gate&&voice.owner===owner&&voice.channel===channel) {
        voice.keyDown=0;
        if(next.sustain?.[owner+':'+channel])continue;
        releaseVoice(session,index);
        voice.gate=0;voice.releasedAt=event.at;voice.releaseLevel=voice.envelopeLevel;voice.envelopeStage='release';
      }
    }
    return next;
  }
  if(event.type==='sustain') {
    if(typeof event.down!=='boolean')throw new GraphContractError('invalid-event','Sustain must be boolean');
    next.sustain ??= {};
    next.sustain[owner+':'+channel]=event.down;
    if(!event.down)for(const [index,voice] of next.voices.entries()) {
      if(voice.gate&&!voice.keyDown&&voice.owner===owner&&voice.channel===channel) {
        releaseVoice(session,index);
        voice.gate=0;voice.releasedAt=event.at;voice.releaseLevel=voice.envelopeLevel;voice.envelopeStage='release';
      }
    }
    return next;
  }
  if(!['note-on','note-off'].includes(event.type)||!Number.isInteger(event.note)||event.note<0||event.note>127)
    throw new GraphContractError('invalid-event','Expected a MIDI note-on, note-off or panic');
  if(event.type==='note-on') {
    const velocity=event.velocity ?? 100;
    if(!Number.isInteger(velocity)||velocity<1||velocity>127)throw new GraphContractError('invalid-event','Invalid note velocity');
    const index=chooseMainVoice(next.voices),stamp=(next.stamp%1000000)+1;
    startVoice(session,index,event.note,Math.min(.4,.03+velocity/127*.37));
    session.parameters([{nodeId:envelopeId(index),id:4,value:1},{nodeId:envelopeId(index),id:5,value:stamp}]);
    next.stamp=stamp;
    next.voices[index]={...emptyVoice(),active:true,note:event.note,gate:1,stamp,owner,channel,
      startedAt:event.at,velocity,keyDown:1,envelopeStage:'attack'};
  } else for(const [index,voice] of next.voices.entries()) {
    if(voice.gate && voice.note===event.note && voice.owner===owner && voice.channel===channel) {
      voice.keyDown=0;
      if(next.sustain?.[owner+':'+channel])continue;
      releaseVoice(session,index);
      voice.gate=0;voice.releasedAt=event.at;voice.releaseLevel=voice.envelopeLevel;voice.envelopeStage='release';
    }
  }
  return next;
}

return { graph, view, paint, onControl, onEvent, eventState, eventStateSchema };

const {createGraphWorkspace,GraphContractError}=manifold;
const MAIN_SYNTH = '/midi/synth';
const voiceBase = index => `${MAIN_SYNTH}/voice/${index}`;
const nodePath = (index, name) => `${voiceBase(index)}/nodes/${name}`;
const ranges = {
  waveform: [0, 7, 1, true], pulseWidth: [0.01, 0.99, 0.5],
  drive: [0, 20, 0], driveShape: [0, 3, 0, true], driveBias: [-1, 1, 0],
  driveMix: [0, 1, 1], unison: [1, 8, 1, true], detune: [0, 100, 0],
  spread: [0, 1, 0], 'blend/amount': [0, 1, 0.5],
};
const oscillatorIds = { waveform: 0, pulseWidth: 4, drive: 5, driveShape: 6,
  driveBias: 7, driveMix: 8, unison: 10, detune: 11, spread: 12 };

/** A real Main voice branch. A missing sample input is silent, as in the old graph. */
function addMainWaveVoice(graph, { index, firstNodeId, sample = null }) {
  const add = (type, name, offset) => {
    const node = graph.add(type.startsWith('mixer') ? 'mixer' : type, { id: firstNodeId + offset,
      config: type.startsWith('mixer') ? { inputs: Number(type.slice(5)) } : {} });
    graph.registerInstance(nodePath(index, name), node);
    return node;
  };
  const oscillator = add('extended-oscillator', 'oscillator', 0);
  const mix = add('crossfader', 'mix', 1);
  const direction = add('crossfader', 'direction', 2);
  const select = add('crossfader', 'base_select', 3);
  const branches = add('mixer3', 'branches', 4);
  const voice = add('mixer4', 'output', 5);
  for (const node of [mix, direction]) {
    graph.connect(oscillator.output('out'), node.input('a'));
    if (sample) graph.connect(sample, node.input('b'));
  }
  graph.setParameter(select, 0, -1);
  graph.connect(mix.output('out'), select.input('a'));
  graph.connect(direction.output('out'), select.input('b'));
  graph.setParameter(branches, 2, 0).setParameter(branches, 3, 0);
  graph.connect(select.output('out'), branches.input('in-1'));
  for (let input = 1; input <= 3; input++) graph.setParameter(voice, input, 0);
  graph.connect(branches.output('out'), voice.input('in-4'));
  graph.registerParameter(`${voiceBase(index)}/freq`, oscillator, 1,
    { min: 20, max: 8000, default: 220 });
  graph.registerParameter(`${voiceBase(index)}/amp`, oscillator, 2,
    { min: 0, max: 0.5, default: 0 });
  graph.registerControl(`${voiceBase(index)}/gate`, { min: 0, max: 1, default: 0 });
  return { oscillator, mix, direction, select, branches, output: voice };
}

/** Eight independent authored voices; scripts may inspect and replace every node. */
function addMainWaveVoices(graph, { firstNodeId = 10, mixerId = 60 } = {}) {
  const mixer = graph.add('mixer', { id: mixerId, config: { inputs: 8 } });
  graph.registerInstance(`${MAIN_SYNTH}/nodes/voice_mixer`, mixer);
  const voices = Array.from({ length: 8 }, (_, index) => {
    const voice = addMainWaveVoice(graph, { index: index + 1, firstNodeId: firstNodeId + index * 6 });
    graph.connect(voice.output.output('out'), mixer.input(`in-${index + 1}`));
    return voice;
  });
  for (const [key, [min, max, value, discrete = false]] of Object.entries(ranges)) {
    graph.registerControl(`${MAIN_SYNTH}/${key}`, { min, max, default: value, discrete });
  }
  return { voices, output: mixer };
}

/** Main's shared SVF, from midisynth_integration.applyFilterDefaults.
 * The caller chooses its placement in the authored audio graph.
 */
function addMainSynthFilter(graph, { input, nodeId = 130 } = {}) {
  const filter = graph.add('svf', { id: nodeId });
  graph.registerInstance(`${MAIN_SYNTH}/nodes/filter`, filter);
  graph.connect(input, filter.input('audio'));
  for (const [id, name, min, max, value] of [
    [0, 'filterType', 0, 3, 0], [1, 'cutoff', 80, 16000, 3200],
    [2, 'resonance', 0.1, 2, 0.75],
  ]) graph.registerParameter(`${MAIN_SYNTH}/${name}`, filter, id, { min, max, default: value });
  // The public SVF is fully wet with unity drive, matching these old defaults.
  return filter;
}

/** main.lua dry/monitor/master routing, with caller-authored loop and synth buses.
 * The caller supplies real layer inputs/outputs; this function does not substitute
 * an independent LoopCapture for the legacy LoopLayer behavior.
 */
function addMainSignalBranches(graph, { synth, layerInputs = [], layerOutputs = [],
  firstNodeId = 70, connectOutput = true } = {}) {
  if (!synth || layerInputs.length > 4 || layerOutputs.length > 4) {
    throw new GraphContractError('invalid-main-branches', 'Provide a synth output and at most four layer buses');
  }
  const add = (name, type, offset) => {
    const node = graph.add(type.startsWith('mixer') ? 'mixer' : type, { id: firstNodeId + offset,
      config: type.startsWith('mixer') ? { inputs: Number(type.slice(5)) } : {} });
    graph.registerInstance(`/main/nodes/${name}`, node);
    return node;
  };
  const trim = add('input_trim', 'gain', 0), monitor = add('input_monitor', 'gain', 1);
  const synthMonitor = add('synth_monitor', 'gain', 2), send = add('synth_send', 'gain', 3);
  const layers = add('layer_mixer', 'mixer4', 4), mix = add('main_mixer', 'mixer3', 5);
  const master = add('master', 'gain', 6);
  for (const node of [trim, monitor, send, master]) graph.setParameter(node, 0, 1);
  graph.setParameter(synthMonitor, 0, 0.8);
  graph.connect(graph.input.output('out'), trim.input('audio'));
  graph.connect(trim.output('out'), monitor.input('audio'));
  graph.connect(synth, synthMonitor.input('audio'));
  graph.connect(synth, send.input('audio'));
  // The legacy graph permits fan-in to a layer input. Explicit sum nodes retain
  // the two contributions in the portable contract's single-source input model.
  layerInputs.forEach((target, index) => {
    const sum = add(`layer_${index + 1}_input`, 'sum2', 7 + index);
    graph.connect(trim.output('out'), sum.input('a'));
    graph.connect(send.output('out'), sum.input('b'));
    graph.connect(sum.output('out'), target);
  });
  layerOutputs.forEach((source, index) => graph.connect(source, layers.input(`in-${index + 1}`)));
  graph.connect(synthMonitor.output('out'), mix.input('in-1'));
  graph.connect(layers.output('out'), mix.input('in-2'));
  graph.connect(monitor.output('out'), mix.input('in-3'));
  graph.connect(mix.output('out'), master.input('audio'));
  if (connectOutput) graph.connect(master.output('out'), graph.output.input('in'));
  for (const [name, node, value] of [['inputTrim', trim, 1], ['inputMonitor', monitor, 1],
    ['output', synthMonitor, 0.8], ['captureSend', send, 1], ['master', master, 1]]) {
    graph.registerParameter(`${MAIN_SYNTH}/${name}`, node, 0, { min: 0, max: 2, default: value });
  }
  return { trim, monitor, synthMonitor, send, layers, mix, master };
}

function buildGraph({ captureLayers = false } = {}) {
  const graph = createGraphWorkspace().setInputSource('external');
  const { output } = addMainWaveVoices(graph);
  const captures = captureLayers ? Array.from({ length: 4 }, (_, index) => {
    const node = graph.add('retrospective-capture', { id: 90 + index });
    graph.registerInstance(`/main/layer/${index + 1}/capture`, node);
    return node.input('audio');
  }) : [];
  addMainSignalBranches(graph, { synth: output.output('out'), layerInputs: captures });
  return graph;
}


function chooseMainVoice(voices) {
  const idle = voices.findIndex(v => !v.active || v.envelopeStage === 'idle');
  if (idle >= 0) return idle;
  let release = -1;
  for (let index = 0; index < voices.length; index++) {
    if (voices[index].envelopeStage === 'release' &&
      (release < 0 || voices[index].envelopeLevel < voices[release].envelopeLevel)) release = index;
  }
  if (release >= 0) return release;
  return voices.reduce((oldest, v, index) => v.stamp < voices[oldest].stamp ? index : oldest, 0);
}

// Visual sampling port of Main/lib/ui/oscillator_preview.lua. This produces
// drawing points only. The authored Rust oscillator remains the audio processor.
const previewClamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const previewFract=v=>v-Math.floor(v);
function oscillatorPreviewWave(type,p,width){
  p=previewFract(p);
  switch(type){
    case 0:return Math.sin(p*2*Math.PI);
    case 1:return 2*p-1;
    case 2:return p<.5?1:-1;
    case 3:return p<.5?4*p-1:3-4*p;
    case 4:return ((2*p-1)+Math.sin(p*2*Math.PI))*.5;
    case 5:return (previewFract(Math.sin(p*43758.5453))*2-1)*.5;
    case 6:return p<width?1:-1;
    case 7:return ((2*p-1)+(2*previewFract(p*1.01)-1)*.5+(2*previewFract(p*.99)-1)*.5)*.5;
  }
  return 0;
}
function oscillatorPreviewRecipe(type,width){
  const out=[],add=(ratio,amplitude,phase=0)=>{if(amplitude>1e-6&&out.length<12)out.push({ratio,amplitude,phase});};
  if(type===0)add(1,1);
  else if(type===1||type===4)for(let h=1;h<=12;h++)add(h,type===1?1/h:(h===1?.45:0)+.55/h);
  else if(type===2||type===3)for(let i=0;i<12;i++){const h=2*i+1;add(h,type===2?1/h:1/(h*h),type===2?0:(i%2?1:-1)*Math.PI*.5);}
  else if(type===5){const r=[1,1.37,1.93,2.58,3.11,3.93,5.17,6.44,8.13,10.37,13.11,16.51],a=[1,.91,.82,.74,.67,.60,.52,.45,.38,.31,.25,.2],p=[0,.63,1.42,2.17,.88,2.74,1.11,2.49,.37,1.96,2.81,.94];r.forEach((v,i)=>add(v,a[i],p[i]));}
  else if(type===6)for(let h=1;h<=12;h++){const c=Math.sin(Math.PI*h*width);add(h,Math.abs(c)/h,c<0?Math.PI:0);}
  else if(type===7){const d=[-18,-7,0,8,19],g=[.55,.82,1,.79,.5],p=[.17,.51,0,.33,.74];d.forEach((v,i)=>add(2**(v/1200),g[i],p[i]));}
  return out;
}
function oscillatorPreviewDrive(x,drive,shape,bias){
  const clip=v=>previewClamp(v,-1,1);
  if(drive<=.0001)return clip(x);
  const transfer=value=>{
    if(shape===1){const g=1+drive*1.35;return Math.atan(value*g)/Math.atan(g);}
    if(shape===2)return clip(value*(1+drive*1.2));
    if(shape===3){let v=previewClamp(value*(1+drive*1.1),-32,32);while(v>1||v< -1)v=v>1?2-v:-2-v;return v;}
    const g=1+drive*.85;return Math.tanh(value*g)/Math.tanh(g);
  };
  const offset=bias*.75,center=transfer(offset),normal=Math.max(1e-6,Math.abs(transfer(1+offset)-center),Math.abs(transfer(-1+offset)-center));
  return clip((transfer(x+offset)-center)/normal);
}
function oscillatorPreviewCurves(controls){
