  const recipe=oscillatorPreviewRecipe(type,width).slice(0,Math.max(1,Math.round(controls.additivePartials??8)));
  const tilt=controls.additiveTilt??0,drift=controls.additiveDrift??0;
  const partials=recipe.map(p=>({ratio:Math.max(.1,p.ratio*(1+Math.sin(p.ratio*2.173+type*.53)*drift*.035*(1+p.ratio*.05))),phase:p.phase+Math.sin(p.ratio*1.618+type*.37)*drift*.85,amp:p.amplitude*Math.max(.12,p.ratio**(tilt*.85))}));
